import sqlite3
import json
from contextlib import contextmanager

DB = "surplus_ledger.sqlite3"

def connect():
    con = sqlite3.connect(DB, timeout=30, isolation_level=None)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA foreign_keys=ON")
    con.execute("PRAGMA busy_timeout=30000")
    con.execute("PRAGMA synchronous=FULL")
    return con

def install():
    con = connect()
    try:
        con.execute("PRAGMA journal_mode=WAL")
        con.executescript('''
CREATE TABLE IF NOT EXISTS lots (
    id INTEGER PRIMARY KEY,
    source TEXT NOT NULL,
    source_lot TEXT NOT NULL,
    intake_payload TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'intake'
      CHECK(state IN ('intake','verified','awarded','funded',
                      'removed','ready','sold','closed','scrapped')),
    cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(cost_cents >= 0),
    bid_limit_cents INTEGER NOT NULL CHECK(bid_limit_cents >= 0),
    score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),
    UNIQUE(source, source_lot)
);
CREATE TABLE IF NOT EXISTS operations (
    id INTEGER PRIMARY KEY,
    op_key TEXT NOT NULL UNIQUE,
    payload TEXT NOT NULL,
    lot_id INTEGER REFERENCES lots(id),
    action TEXT NOT NULL,
    evidence TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS accounts (
    name TEXT PRIMARY KEY
);
INSERT OR IGNORE INTO accounts(name) VALUES
 ('cash'),('clearing'),('inventory'),('receivable'),
 ('revenue'),('cogs'),('opex'),('capital');
CREATE TABLE IF NOT EXISTS entries (
    operation_id INTEGER NOT NULL REFERENCES operations(id),
    line_number INTEGER NOT NULL,
    account TEXT NOT NULL REFERENCES accounts(name),
    cents INTEGER NOT NULL CHECK(cents != 0),
    PRIMARY KEY(operation_id, line_number)
);
CREATE TRIGGER IF NOT EXISTS operations_no_update
BEFORE UPDATE ON operations BEGIN
 SELECT RAISE(ABORT, 'immutable operation');
END;
CREATE TRIGGER IF NOT EXISTS operations_no_delete
BEFORE DELETE ON operations BEGIN
 SELECT RAISE(ABORT, 'immutable operation');
END;
CREATE TRIGGER IF NOT EXISTS entries_no_update
BEFORE UPDATE ON entries BEGIN
 SELECT RAISE(ABORT, 'immutable entry');
END;
CREATE TRIGGER IF NOT EXISTS entries_no_delete
BEFORE DELETE ON entries BEGIN
 SELECT RAISE(ABORT, 'immutable entry');
END;
''')
    finally:
        con.close()

@contextmanager
def transaction():
    con = connect()
    try:
        con.execute("BEGIN IMMEDIATE")
        yield con
        con.commit()
    except BaseException:
        con.rollback()
        raise
    finally:
        con.close()

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def cents(value, allow_zero=False):
    if type(value) is not int:
        raise ValueError("integer cents required")
    if value < 0 or (value == 0 and not allow_zero):
        raise ValueError("amount outside permitted range")
    return value

def move(key, lot_id, action, evidence, amount=0, checks=None):
    cents(amount, True)
    if not key or not evidence:
        raise ValueError("operation key and evidence required")
    checks = {} if checks is None else checks
    payload = canonical({
        "lot": lot_id, "action": action, "evidence": evidence,
        "amount": amount, "checks": checks
    })
    with transaction() as con:
        prior = replay(con, key, payload)
        if prior is not None:
            return prior
        lot = con.execute(
            "SELECT * FROM lots WHERE id=?", (lot_id,)
        ).fetchone()
        if lot is None:
            raise ValueError("lot does not exist")
        routes = {
            "verify": (("intake",), "verified"),
            "award": (("verified",), "awarded"),
            "fund": (("awarded",), "funded"),
            "remove": (("funded",), "removed"),
            "repair": (("removed", "ready"), lot["state"]),
            "ready": (("removed",), "ready"),
            "sell": (("ready",), "sold"),
            "close": (("sold",), "closed"),
            "scrap": (("removed", "ready"), "scrapped")
        }
        if action not in routes:
            raise ValueError("unsupported transition")
        allowed, target = routes[action]
        if lot["state"] not in allowed:
            raise ValueError("stale or invalid transition")
        if action == "verify":
            required = {"eligibility", "ownership", "restrictions",
                        "removal", "economics"}
            if set(checks) != required:
                raise ValueError("five verification checks required")
            if any(value is not True for value in checks.values()):
                raise ValueError("verification evidence incomplete")
        elif checks:
            raise ValueError("checks belong only to verification")
        if action in ("fund", "repair", "sell"):
            cents(amount)
        elif amount:
            raise ValueError("transition does not accept an amount")
        cost = lot["cost_cents"]
        lines = []
        if action == "fund":
            cost = amount
            lines = [("clearing", amount), ("cash", -amount)]
        elif action == "remove":
            lines = [("inventory", cost), ("clearing", -cost)]
        elif action == "repair":
            cost += amount
            lines = [("inventory", amount), ("cash", -amount)]
        elif action == "sell":
            lines = [("receivable", amount), ("revenue", -amount),
                     ("cogs", cost), ("inventory", -cost)]
        elif action == "scrap":
            lines = [("cogs", cost), ("inventory", -cost)]
        elif action == "close":
            if lot_balance(con, lot_id, "receivable") != 0:
                raise ValueError("uncollected receivable")
        op_id = record(con, key, payload, lot_id, action, evidence, lines)
        con.execute(
            "UPDATE lots SET state=?,cost_cents=? WHERE id=?",
            (target, cost, lot_id)
        )
        return op_id

def replay(con, key, payload):
    row = con.execute(
        "SELECT id,payload FROM operations WHERE op_key=?", (key,)
    ).fetchone()
    if row is None:
        return None
    if row["payload"] != payload:
        raise ValueError("operation key reused with different payload")
    return row["id"]

def lot_balance(con, lot_id, account):
    row = con.execute(
        "SELECT COALESCE(SUM(e.cents),0) AS balance "
        "FROM entries e JOIN operations o ON o.id=e.operation_id "
        "WHERE o.lot_id=? AND e.account=?", (lot_id, account)
    ).fetchone()
    return row["balance"]

def record(con, key, payload, lot_id, action, evidence, lines):
    if not key or not evidence:
        raise ValueError("operation key and evidence required")
    if any(type(value) is not int or value == 0
           for account, value in lines):
        raise ValueError("nonzero integer journal lines required")
    if sum(value for account, value in lines) != 0:
        raise ValueError("unbalanced journal")
    cur = con.execute(
        "INSERT INTO operations(op_key,payload,lot_id,action,evidence) "
        "VALUES(?,?,?,?,?)", (key, payload, lot_id, action, evidence)
    )
    op_id = cur.lastrowid
    con.executemany(
        "INSERT INTO entries(operation_id,line_number,account,cents) "
        "VALUES(?,?,?,?)",
        [(op_id, index, account, value)
         for index, (account, value) in enumerate(lines, 1)]
    )
    return op_id

def cash_event(key, action, amount, evidence, lot_id=None):
    cents(amount)
    if action not in ("collect", "expense", "seed"):
        raise ValueError("unsupported cash event")
    if action != "collect" and lot_id is not None:
        raise ValueError("general cash event cannot target a lot")
    payload = canonical({
        "action": action, "amount": amount,
        "evidence": evidence, "lot": lot_id
    })
    with transaction() as con:
        prior = replay(con, key, payload)
        if prior is not None:
            return prior
        if action == "collect":
            row = con.execute(
                "SELECT state FROM lots WHERE id=?", (lot_id,)
            ).fetchone()
            if row is None or row["state"] != "sold":
                raise ValueError("collection requires sold lot")
            due = lot_balance(con, lot_id, "receivable")
            if amount > due:
                raise ValueError("collection exceeds receivable")
            lines = [("cash", amount), ("receivable", -amount)]
        elif action == "expense":
            lines = [("opex", amount), ("cash", -amount)]
        else:
            lines = [("cash", amount), ("capital", -amount)]
        return record(
            con, key, payload, lot_id, action, evidence, lines
        )

def qa(expected_bank_cents=None):
    con = connect()
    try:
        con.execute("BEGIN")
        if con.execute("PRAGMA integrity_check").fetchone()[0] != "ok":
            raise ValueError("database integrity check failed")
        if con.execute("PRAGMA foreign_key_check").fetchone():
            raise ValueError("broken foreign key")
        bad = con.execute(
            "SELECT o.id FROM operations o LEFT JOIN entries e "
            "ON e.operation_id=o.id GROUP BY o.id "
            "HAVING COALESCE(SUM(e.cents),0) != 0"
        ).fetchone()
        if bad:
            raise ValueError("unbalanced operation")
        for row in con.execute("SELECT * FROM lot_reconciliation"):
            inventory = (row["cost_cents"]
                         if row["state"] in ("removed", "ready") else 0)
            clearing = (row["cost_cents"]
                        if row["state"] == "funded" else 0)
            if row["inventory_cents"] != inventory:
                raise ValueError("inventory differs from custody state")
            if row["clearing_cents"] != clearing:
                raise ValueError("acquisition clearing differs from state")
            if row["due_cents"] < 0:
                raise ValueError("negative lot receivable")
            if row["state"] != "sold" and row["due_cents"] != 0:
                raise ValueError("receivable exists outside sold state")
        balance = con.execute(
            "SELECT cents FROM account_balances WHERE account='cash'"
        ).fetchone()["cents"]
        if expected_bank_cents is not None:
            if balance != expected_bank_cents:
                raise ValueError("bank reconciliation difference")
        con.commit()
        return True
    finally:
        con.close()

